const input = $input.first().json;
const body = input.body || input;

const errors = [];
const action = body.action || 'create';

// Common validation
if (!body.user_id) {
  errors.push('Missing required parameter: user_id');
}

// Action-specific validation
if (action === 'create') {
  // discord_channel_id is optional (used for tracking, not required for DM notifications)
  if (!body.label) {
    errors.push('Missing required parameter: label');
  }
  if (!body.duration_minutes) {
    errors.push('Missing required parameter: duration_minutes');
  } else if (body.duration_minutes < 1 || body.duration_minutes > 1440) {
    errors.push('duration_minutes must be between 1 and 1440 (24h max)');
  }
} else if (action === 'cancel') {
  if (!body.timer_id) {
    errors.push('Missing required parameter: timer_id');
  }
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    action: action,
    user_id: body.user_id,
    discord_channel_id: body.discord_channel_id || null,  // Optional - for tracking
    timer_id: body.timer_id,
    label: body.label,
    duration_minutes: body.duration_minutes,
    recipe_id: body.recipe_id,
    recipe_title: body.recipe_title,
    status_filter: body.status || 'active',
    api_base_url: body.api_base_url || process.env.API_BASE_URL || 'http://api.torah.solutions/api'
  }
}];

