const input = $input.first().json;
const prevData = $('Validate Input').first().json;

try {
  // Check for API error
  if (input.detail) {
    return [{
      json: {
        success: false,
        error: {
          code: 404,
          message: input.detail,
          status: 'NOT_FOUND'
        },
        meta: { provider: 'api', action: prevData.action }
      }
    }];
  }

  // Format based on action
  if (prevData.action === 'create') {
    return [{
      json: {
        success: true,
        data: {
          timer_id: input.id,
          label: input.label,
          duration_minutes: input.duration_minutes,
          expires_at: input.expires_at,
          status: input.status
        },
        meta: { provider: 'api', action: 'create' }
      }
    }];
  } else if (prevData.action === 'list') {
    const timers = (input.timers || []).map(t => ({
      timer_id: t.id,
      label: t.label,
      duration_minutes: t.duration_minutes,
      expires_at: t.expires_at,
      remaining_seconds: t.remaining_seconds,
      recipe_title: t.recipe_title,
      status: t.status
    }));
    return [{
      json: {
        success: true,
        data: {
          timers: timers,
          total: input.total || timers.length
        },
        meta: { provider: 'api', action: 'list' }
      }
    }];
  } else if (prevData.action === 'cancel') {
    return [{
      json: {
        success: true,
        data: {
          message: input.message || 'Timer cancelled'
        },
        meta: { provider: 'api', action: 'cancel' }
      }
    }];
  }

  return [{ json: { success: true, data: input, meta: { provider: 'api' } } }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to process API response: ' + e.message,
        status: 'PROCESS_ERROR'
      },
      meta: { provider: 'api' }
    }
  }];
}
